/* ---------- 落子 / 提子真实录音数据（由源码 sounds/*.mp3 生成，勿手改） ----------
   来源：Sabaki 开源围棋棋盘（MIT）https://github.com/SabakiHQ/Sabaki 的 data/ 目录。
   data/0~4.mp3      = 落子（pachi），131~261ms，44.1kHz 单声道 128kbps
   data/capture0~4.mp3 = 提子，336~496ms
   共 10 个变体 47KB，base64 后 61KB。单文件版构建时会被内联进 HTML，
   原始 mp3 留在源码 sounds/ 目录（不参与构建，仅备查与重新生成）。
   解码后由 app.js 的 prep() 裁掉 mp3 编码器延迟的静音头、统一峰值到 0.88，
   避免"点一下慢半拍"和"一会儿响一会儿轻"。 */
var SFX_REC = {
  // 落子：同一副棋敲在不同位置的 5 次真实录音
  stone: [
    "",
    "",
    "",
    "",
    ""
  ],
  // 提子：棋子被拿走时在盘面上磕碰的声音，比落子长、更闷
  capture: [
    "",
    "",
    "",
    "",
    ""
  ]
};

